-- SPDX-License-Identifier: AGPL-3.0-or-later
-- risk: transforming
-- apps: additive
-- (the feature registry and the setup level catalogue are restated, three settings are seeded; no stored flag moves)
--
-- #4373 (CS11, first file) -- the counterOfflineCash feature: the till keeps selling for cash when it is offline, and the sales are
-- sent once the connection returns (the server side is 0937). Asked for, under till sessions, off by default. Off: nothing changes.
-- The server's copy of the manifest (dart run tool/build_feature_registry_sql.dart), the setup levels that name it
-- (dart run tool/build_setup_steps.dart) and the settings the offline sales are checked against.

-- BEGIN GENERATED SEED (dart run tool/build_settings_seed.dart)
insert into public.setting_definitions
  (key, type, default_value, min_value, max_value, unit, group_key, scopes,
   edit_permission, floor_value, editable, choices, source, note)
values
('counter.offline_max_minutes', 'int', '240'::jsonb, 1, 2880, 'minutes', 'business', array['workspace'], 'workspaceSettings', null, true, null, 'offline cash sales (#4373)', 'How long after the till lost its connection a cash sale made offline is still accepted when it is sent. A later sale is refused and listed for the owner; its cash stays in the drawer count.'),
('counter.offline_max_sales', 'int', '200'::jsonb, 1, 1000, '', 'business', array['workspace'], 'workspaceSettings', null, true, null, 'offline cash sales (#4373)', 'How many cash sales made offline one till session accepts. A further sale is refused and listed for the owner; its cash stays in the drawer count.'),
('counter.offline_price_tolerance_percent', 'int', '0'::jsonb, 0, 100, '', 'business', array['workspace'], 'workspaceSettings', null, true, null, 'offline cash sales (#4373)', 'How far, in percent, the price of a sale made offline may differ from the current price of the item when the sale is sent. 0 means the price must be the same; a sale beyond it is refused and listed for the owner.')
on conflict (key) do nothing;
-- END GENERATED SEED

